package modelcatalog

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/easel/fizeau/internal/reasoning"
	"github.com/easel/fizeau/internal/sampling"
)

// Surface identifies a consumer-specific concrete model naming surface.
type Surface string

const (
	SurfaceAgentOpenAI    Surface = "agent.openai"
	SurfaceAgentAnthropic Surface = "agent.anthropic"
	SurfaceCodex          Surface = "codex"
	SurfaceClaudeCode     Surface = "claude-code"
	SurfaceGemini         Surface = "gemini"
)

// ResolveOptions configures compatibility model-reference resolution.
type ResolveOptions struct {
	Surface         Surface
	AllowDeprecated bool
}

// Catalog exposes the loaded v5 model catalog.
type Catalog struct {
	manifest    manifest
	manifestSrc string
}

// Metadata describes the loaded manifest.
type Metadata struct {
	ManifestSource  string
	ManifestVersion int
	CatalogVersion  string
}

// Policy describes one canonical catalog routing policy.
type Policy struct {
	Name       string
	MinPower   int
	MaxPower   int
	AllowLocal bool
	Require    []string
}

// Provider describes one catalog-declared provider system.
type Provider struct {
	Name             string
	Type             string
	IncludeByDefault bool
	Billing          BillingModel
}

// SurfacePolicy is kept as a narrow compatibility container for callers that
// have not yet moved reasoning defaults from surface projections to model entries.
type SurfacePolicy struct {
	ReasoningDefault       reasoning.Reasoning
	PlacementOrder         []string
	MaxInputCostPerMTokUSD *float64
	FailurePolicy          string
}

// ResolvedTarget is the compatibility output for model-reference resolution.
// In v5 CanonicalID is either a policy name or canonical model ID; there is no
// catalog alias concept behind it.
type ResolvedTarget struct {
	Ref                string
	Profile            string
	Family             string
	CanonicalID        string
	ConcreteModel      string
	SurfacePolicy      SurfacePolicy
	Deprecated         bool
	Replacement        string
	CatalogVersion     string
	ManifestSource     string
	ManifestVersion    int
	CostInputPerM      float64
	CostOutputPerM     float64
	CostCacheReadPerM  float64
	CostCacheWritePerM float64
	ContextWindow      int
	SWEBenchVerified   float64
	LiveCodeBench      float64
	BenchmarkAsOf      string
	OpenRouterRefID    string
}

// ModelEligibility describes whether a catalog model can participate in
// unpinned automatic routing or only explicit model pins.
type ModelEligibility struct {
	Power        int
	ExactPinOnly bool
	AutoRoutable bool
}

// Metadata returns the loaded manifest metadata for inspection surfaces.
func (c *Catalog) Metadata() Metadata {
	return Metadata{
		ManifestSource:  c.manifestSrc,
		ManifestVersion: c.manifest.Version,
		CatalogVersion:  c.manifest.CatalogVersion,
	}
}

// Policies returns all canonical policies in deterministic order.
func (c *Catalog) Policies() []Policy {
	names := make([]string, 0, len(c.manifest.Policies))
	for name := range c.manifest.Policies {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]Policy, 0, len(names))
	for _, name := range names {
		policy, _ := c.Policy(name)
		out = append(out, policy)
	}
	return out
}

// Policy returns one canonical policy definition.
func (c *Catalog) Policy(name string) (Policy, bool) {
	name = strings.TrimSpace(name)
	entry, ok := c.manifest.Policies[name]
	if !ok {
		return Policy{}, false
	}
	return Policy{
		Name:       name,
		MinPower:   entry.MinPower,
		MaxPower:   entry.MaxPower,
		AllowLocal: entry.AllowLocal,
		Require:    append([]string(nil), entry.Require...),
	}, true
}

// Providers returns all catalog-declared provider systems in deterministic order.
func (c *Catalog) Providers() []Provider {
	names := make([]string, 0, len(c.manifest.Providers))
	for name := range c.manifest.Providers {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]Provider, 0, len(names))
	for _, name := range names {
		entry := c.manifest.Providers[name]
		billing := BillingModel(entry.Billing)
		if billing == BillingModelUnknown {
			billing = BillingForProviderSystem(entry.Type)
			if billing == BillingModelUnknown {
				billing = BillingForHarness(entry.Type)
			}
		}
		out = append(out, Provider{
			Name:             name,
			Type:             entry.Type,
			IncludeByDefault: entry.IncludeByDefault,
			Billing:          billing,
		})
	}
	return out
}

// UnknownReferenceError indicates that a reference is not known to the catalog.
type UnknownReferenceError struct {
	Ref string
}

func (e *UnknownReferenceError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown reference %q", e.Ref)
}

// MissingSurfaceError indicates that a model cannot be projected to the requested surface.
type MissingSurfaceError struct {
	CanonicalID string
	Surface     Surface
}

func (e *MissingSurfaceError) Error() string {
	return fmt.Sprintf("modelcatalog: reference %q has no mapping for surface %q", e.CanonicalID, e.Surface)
}

// DeprecatedTargetError indicates that a deprecated or stale model was resolved in strict mode.
type DeprecatedTargetError struct {
	CanonicalID       string
	Status            string
	Replacement       string
	SuggestedProfile  string
	SuggestedMinPower int
	SuggestedMaxPower int
}

func (e *DeprecatedTargetError) Error() string {
	if e.Replacement == "" {
		return fmt.Sprintf("modelcatalog: reference %q is %s", e.CanonicalID, e.Status)
	}
	return fmt.Sprintf("modelcatalog: reference %q is %s; use %q", e.CanonicalID, e.Status, e.Replacement)
}

// Current resolves a policy to its selected concrete model for a surface.
func (c *Catalog) Current(policy string, opts ResolveOptions) (ResolvedTarget, error) {
	return c.Resolve(policy, opts)
}

// Resolve resolves a canonical policy or model ID to a concrete model ID.
func (c *Catalog) Resolve(ref string, opts ResolveOptions) (ResolvedTarget, error) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
	}
	if opts.Surface == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: ref, Surface: opts.Surface}
	}
	if policy, ok := c.policyForReference(ref); ok {
		return c.resolvePolicy(ref, policy, opts)
	}
	if entry, ok := c.manifest.Models[ref]; ok && surfaceModelID(ref, entry, opts.Surface) == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: ref, Surface: opts.Surface}
	}
	if modelID, entry, ok := c.lookupModelVariant(ref); ok && surfaceModelID(modelID, entry, opts.Surface) == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: modelID, Surface: opts.Surface}
	}
	modelID, entry, concrete, ok := c.modelForSurface(ref, opts.Surface)
	if !ok {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
	}
	return c.resolvedFromModel(ref, "", modelID, concrete, entry, opts)
}

func (c *Catalog) resolvePolicy(ref string, policy Policy, opts ResolveOptions) (ResolvedTarget, error) {
	displayName := policyDisplayNameForRef(ref, policy.Name)
	candidates := c.policyCandidates(policy, opts.Surface)
	if len(candidates) == 0 {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: displayName, Surface: opts.Surface}

package routing

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

var (
	errHarnessModelIncompatible     = errors.New("routing: harness model incompatible")
	errPolicyRequirementUnsatisfied = errors.New("routing: policy requirement unsatisfied")
	errUnknownPolicy                = errors.New("routing: unknown policy")
	errUnsatisfiablePin             = errors.New("routing: unsatisfiable pin")
	errAllProvidersQuotaExhausted   = errors.New("routing: all providers quota exhausted")
)

// ErrHarnessModelIncompatible reports an explicit Harness+Model pin that the
// harness allow-list cannot serve.
type ErrHarnessModelIncompatible struct {
	// Harness is the canonical harness name supplied by the caller.
	Harness string
	// Model is the exact concrete model pin supplied by the caller.
	Model string
	// SupportedModels is the harness allow-list that rejected Model.
	SupportedModels []string
}

func (e ErrHarnessModelIncompatible) Error() string {
	return fmt.Sprintf("model %q is not supported by harness %q; supported models: %s", e.Model, e.Harness, strings.Join(e.SupportedModels, ", "))
}

func (e ErrHarnessModelIncompatible) Is(target error) bool {
	switch target.(type) {
	case ErrHarnessModelIncompatible, *ErrHarnessModelIncompatible:
		return true
	default:
		return errors.Is(errHarnessModelIncompatible, target)
	}
}

func (e ErrHarnessModelIncompatible) Unwrap() error {
	return errHarnessModelIncompatible
}

// ErrPolicyRequirementUnsatisfied reports a hard policy requirement that no
// candidate, or an explicit caller pin, can satisfy.
type ErrPolicyRequirementUnsatisfied struct {
	Policy       string
	Requirement  string
	AttemptedPin string
	Rejected     int
}

func (e ErrPolicyRequirementUnsatisfied) Error() string {
	if e.AttemptedPin != "" {
		return fmt.Sprintf("policy %q requires %s but conflicts with %s", e.Policy, e.Requirement, e.AttemptedPin)
	}
	return fmt.Sprintf("policy %q has no candidate satisfying %s: %d candidates rejected", e.Policy, e.Requirement, e.Rejected)
}

func (e ErrPolicyRequirementUnsatisfied) Is(target error) bool {
	switch target.(type) {
	case ErrPolicyRequirementUnsatisfied, *ErrPolicyRequirementUnsatisfied:
		return true
	default:
		return errors.Is(errPolicyRequirementUnsatisfied, target)
	}
}

func (e ErrPolicyRequirementUnsatisfied) Unwrap() error {
	return errPolicyRequirementUnsatisfied
}

// ErrUnknownPolicy reports a policy name outside the routing engine's
// canonical v0.11 policy vocabulary.
type ErrUnknownPolicy struct {
	Policy string
}

func (e ErrUnknownPolicy) Error() string {
	return fmt.Sprintf("unknown policy %q", e.Policy)
}

func (e ErrUnknownPolicy) Is(target error) bool {
	switch target.(type) {
	case ErrUnknownPolicy, *ErrUnknownPolicy:
		return true
	default:
		return errors.Is(errUnknownPolicy, target)
	}
}

func (e ErrUnknownPolicy) Unwrap() error {
	return errUnknownPolicy
}

// ErrUnsatisfiablePin reports explicit caller pins that cannot all be true at
// once, such as a harness/model pair where the harness cannot serve the model.
type ErrUnsatisfiablePin struct {
	Pin    string
	Reason string
}

func (e ErrUnsatisfiablePin) Error() string {
	if e.Reason == "" {
		return fmt.Sprintf("unsatisfiable pin %s", e.Pin)
	}
	return fmt.Sprintf("unsatisfiable pin %s: %s", e.Pin, e.Reason)
}

func (e ErrUnsatisfiablePin) Is(target error) bool {
	switch target.(type) {
	case ErrUnsatisfiablePin, *ErrUnsatisfiablePin:
		return true
	default:
		return errors.Is(errUnsatisfiablePin, target)
	}
}

func (e ErrUnsatisfiablePin) Unwrap() error {
	return errUnsatisfiablePin
}

// ErrAllProvidersQuotaExhausted reports that every routing candidate that
// would have been eligible for the request was filtered out solely because
// its provider is currently in quota_exhausted state. RetryAfter is the
// earliest expected provider-recovery time across the exhausted set.
type ErrAllProvidersQuotaExhausted struct {
	RetryAfter         time.Time
	ExhaustedProviders []string
}

func (e ErrAllProvidersQuotaExhausted) Error() string {
	if len(e.ExhaustedProviders) == 0 {
		return "all eligible providers are quota-exhausted"
	}
	return fmt.Sprintf("all eligible providers are quota-exhausted: %s (retry after %s)",
		strings.Join(e.ExhaustedProviders, ", "), e.RetryAfter.Format(time.RFC3339))
}

func (e ErrAllProvidersQuotaExhausted) Is(target error) bool {
	switch target.(type) {
	case ErrAllProvidersQuotaExhausted, *ErrAllProvidersQuotaExhausted:
		return true
	default:
		return errors.Is(errAllProvidersQuotaExhausted, target)
	}
}

func (e ErrAllProvidersQuotaExhausted) Unwrap() error {
	return errAllProvidersQuotaExhausted
}

