54	func ScanContent(path string, content []byte) []Finding {
55		var findings []Finding
56		scanner := bufio.NewScanner(strings.NewReader(string(content)))
57		buf := make([]byte, 0, 64*1024)
58		scanner.Buffer(buf, 1024*1024)
59		lineNo := 0
60		for scanner.Scan() {
61			lineNo++
62			line := scanner.Text()
63			col := strings.Index(line, "target")
64			if col < 0 || allowedTargetLine(path, line) {
65				continue
66			}
67			findings = append(findings, Finding{
68				Path:   filepath.ToSlash(path),
69				Line:   lineNo,
70				Column: col + 1,
71				Text:   strings.TrimSpace(line),
72			})
73		}
74		return findings
75	}
